const calc=window.CavaCalculations;
const money = n => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
const num = n => new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(Number(n)||0);
const escapeHtml = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const baseQuantities=[['Serviços preliminares','Limpeza do terreno','m²',180,0,'Estimado'],['Serviços preliminares','Locação da obra','m²',180,0,'Necessita revisão'],['Alvenaria','Alvenaria bloco cerâmico','m²',246.5,8,'Confirmado'],['Pisos','Porcelanato','m²',124.8,10,'Estimado'],['Pisos','Cerâmica','m²',42,10,'Necessita revisão'],['Revestimentos','Revestimento cerâmico','m²',88.4,12,'Estimado'],['Pintura','Pintura interna','m²',382,8,'Estimado'],['Pintura','Pintura externa','m²',146,8,'Necessita revisão'],['Esquadrias','Porta','un',11,0,'Confirmado'],['Esquadrias','Janela','un',9,0,'Estimado']];
