const seed={projects:[{id:'p1',name:'Residência Silva',client:'Roberto Silva',city:'Campinas',state:'SP',area:180,floors:2,type:'Residencial',standard:'Médio',status:'Em revisão',updated:'2026-09-28',address:'Rua das Acácias, 184',notes:''},{id:'p2',name:'Clínica Horizonte',client:'Horizonte Saúde Ltda.',city:'Jundiaí',state:'SP',area:320,floors:1,type:'Comercial',standard:'Alto',status:'Em análise',updated:'2026-09-24',address:'Av. Nove de Julho, 1200',notes:''},{id:'p3',name:'Reforma Ap. Pinheiros',client:'Ana Martins',city:'São Paulo',state:'SP',area:96,floors:1,type:'Reforma',standard:'Médio',status:'Rascunho',updated:'2026-09-19',address:'Rua dos Pinheiros, 90',notes:''}],quantities:baseQuantities.map((q,i)=>({id:'q'+i,category:q[0],description:q[1],unit:q[2],quantity:q[3],loss:q[4],status:q[5],document:'Arquitetura - Residência Silva.pdf',page:i===3?18:7,room:i===3?'Sala de estar':'Geral',element:q[1],method:'Quantidade informada para demonstração; revisar com base no projeto.'})),items:baseItems.map((x,i)=>({id:'b'+i,group:x[0],description:x[1],unit:x[2],quantity:x[3],price:x[4],code:'CAV-'+String(i+1).padStart(3,'0')})),prices:[{code:'INS-001',description:'Cimento Portland CP II 50 kg',category:'Material',unit:'sc',price:39.9,supplier:'Depósito Central',region:'Campinas, SP',date:'2026-09-20',source:'Cotação local'},{code:'INS-002',description:'Bloco cerâmico 9 x 19 x 19 cm',category:'Material',unit:'un',price:1.28,supplier:'Cerâmica União',region:'Campinas, SP',date:'2026-09-18',source:'Cotação local'},{code:'MO-001',description:'Pedreiro',category:'Mão de obra',unit:'h',price:32,supplier:'Tabela própria',region:'São Paulo, SP',date:'2026-09-15',source:'Referência própria'},{code:'MO-002',description:'Servente',category:'Mão de obra',unit:'h',price:22,supplier:'Tabela própria',region:'São Paulo, SP',date:'2026-09-15',source:'Referência própria'}],compositions:[{code:'COMP-001',description:'Alvenaria de bloco cerâmico',unit:'m²',items:[{description:'Bloco cerâmico',coef:25,price:1.28},{description:'Argamassa de assentamento',coef:0.018,price:780},{description:'Pedreiro',coef:0.8,price:32},{description:'Servente',coef:0.6,price:22}]}],bdi:22,activeProject:'p1'};
// Seed antigo preservado somente como fixture de desenvolvimento; usuários começam sem dados carregados.
let db={projects:[],quantities:[],items:[],prices:[],compositions:[],budgets:[],budgetGroups:[],allQuantities:[],bdi:0,activeProject:'',documents:[]};
let cavaSupabase=null,authUser=null,companyId=null;
let current='dashboard',projectQuery='',quantityQuery='';
function uuid(){return crypto.randomUUID()}
function sbError(error){if(error){console.error(error);throw new Error(error.message||'Falha ao salvar no Supabase.')}}
async function persistQuantity(q){const row={id:q.id,company_id:companyId,project_id:db.activeProject,category:q.category,description:q.description,unit:q.unit,quantity:q.quantity,loss_percent:q.loss,status:q.status};let {error}=await cavaSupabase.from('quantities').upsert(row);sbError(error);for(const source of q.sources||[]){const sourceRow={...(source.id?{id:source.id}:{}),company_id:companyId,project_id:db.activeProject,quantity_id:q.id,document_id:source.document_id||null,page:Number(source.page)||null,room_id:source.room_id||null,element_id:source.element_id||null,room_label:source.room_label||null,element_label:source.element_label||null,observation:source.observation||null,calculation_method:source.calculation_method||null};let out=await cavaSupabase.from('quantity_sources').upsert(sourceRow).select('id').single();sbError(out.error);source.id=out.data.id}const final=calc.finalQuantity(q.quantity,q.loss);let linked=await cavaSupabase.from('budget_items').update({quantity:final,unit:q.unit}).eq('company_id',companyId).eq('quantity_id',q.id);sbError(linked.error);if(db.activeProject)await loadProjectData(db.activeProject)}
async function persistPrice(p){let {error}=await cavaSupabase.from('price_items').upsert({id:p.id,company_id:companyId,code:p.code,description:p.description,category:p.category,unit:p.unit,unit_price:p.price,supplier:p.supplier,region:p.region,source:p.source,price_date:p.date});sbError(error)}
async function updateBdi(value){let next=Number(value)||0;try{if(!db.activeProject)throw new Error('Selecione um projeto para configurar o BDI do orçamento.');let budget=await ensureBudget();let {error}=await cavaSupabase.from('budgets').update({bdi_percent:next}).eq('id',budget.id).eq('company_id',companyId);sbError(error);db.bdi=next;budget.bdi_percent=next;render();toast('BDI deste orçamento salvo.')}catch(err){toast(err.message)}}
async function logout(){await cavaSupabase.auth.signOut();authUser=null;companyId=null;authPage('Você saiu da sua conta.')}
async function ensureBudget(){let budget=db.budgets.find(x=>x.project_id===db.activeProject);if(budget)return budget;let {data,error}=await cavaSupabase.from('budgets').insert({company_id:companyId,project_id:db.activeProject,name:'Orçamento principal',bdi_percent:Number(db.defaultBdi??db.bdi)||0,created_by:authUser.id}).select('*').single();sbError(error);db.budgets.push(data);return data}
function effectiveBudgetQuantity(item){let linked=db.quantities.find(q=>q.id===item.quantity_id);return linked?calc.finalQuantity(linked.quantity,linked.loss):Number(item.quantity)}
function effectiveBudgetPrice(item){let linked=db.compositions.find(c=>c.id===item.composition_id);return linked?calc.compositionUnitCost(linked.items):Number(item.price)}
async function persistBudgetItem(item){let quantity=db.quantities.find(q=>q.id===item.quantity_id),composition=db.compositions.find(c=>c.id===item.composition_id);if(quantity&&composition&&quantity.unit!==composition.unit)throw new Error('A unidade do quantitativo precisa ser igual à unidade da composição vinculada.');let budget=await ensureBudget();if(quantity){item.quantity=calc.finalQuantity(quantity.quantity,quantity.loss);item.unit=quantity.unit}if(composition){item.price=calc.compositionUnitCost(composition.items);item.unit=composition.unit}let group=(db.budgetGroups||[]).find(g=>g.name===item.group&&g.budget_id===budget.id);if(!group){let r=await cavaSupabase.from('budget_groups').insert({company_id:companyId,budget_id:budget.id,name:item.group,position:(db.budgetGroups||[]).length}).select('*').single();sbError(r.error);group=r.data;db.budgetGroups.push(group)}item.budget_id=budget.id;item.group_id=group.id;let {error}=await cavaSupabase.from('budget_items').upsert({id:item.id,company_id:companyId,budget_id:budget.id,group_id:group.id,quantity_id:item.quantity_id||null,composition_id:item.composition_id||null,code:item.code,description:item.description,unit:item.unit,quantity:item.quantity,unit_price:item.price,position:Math.max(0,db.items.indexOf(item))});sbError(error);await loadProjectData(db.activeProject)}
function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
const pageNames={dashboard:'Dashboard',projetos:'Projetos',orcamentos:'Orçamentos',composicoes:'Composições','precos':'Banco de preços',configuracoes:'Configurações',novo:'Novo orçamento',quantitativos:'Quantitativos'};
function authPage(message=''){document.querySelector('.sidebar').style.display='none';document.querySelector('.topbar').style.display='none';document.querySelector('.app-footer').style.display='none';document.querySelector('.main').style.marginLeft='0';document.querySelector('#app').innerHTML=`<div class="login-shell"><div class="login-card"><div class="login-brand">CAVA<span>+</span> ORÇA</div><h1>Transforme projetos em orçamentos.</h1><div class="subhead" style="margin-bottom:20px">Entre na sua conta para acessar os projetos da sua empresa.</div>${message?`<div class="notice" style="margin-bottom:12px">${escapeHtml(message)}</div>`:''}<form id="loginForm"><div class="field"><label>E-mail</label><input name="email" type="email" required autocomplete="email" placeholder="voce@empresa.com"></div><div class="field"><label>Senha</label><input name="password" type="password" required autocomplete="current-password" minlength="6" placeholder="Sua senha"></div><button class="btn btn-primary" style="width:100%;margin-top:8px">Entrar</button></form><button class="text-link" style="border:0;background:none;margin-top:14px" onclick="authAction('recover')">Esqueci minha senha</button><div style="border-top:1px solid var(--line);margin:18px 0"></div><div class="subhead" style="margin-bottom:10px">Ainda não tem uma conta?</div><button class="btn" style="width:100%" onclick="authAction('signup')">Criar conta e empresa</button><div class="small-muted" style="line-height:1.6;margin-top:15px">Sua empresa e configurações iniciais serão criadas com acesso isolado.</div></div></div>`;document.querySelector('#loginForm').onsubmit=login}
async function authAction(action){if(!cavaSupabase){authPage('Preencha a URL e a chave anon/public em supabase-config.js e aplique supabase/schema.sql.');return}if(action==='recover'){modal('Recuperar senha',`<form id="recoverForm"><div class="field"><label>E-mail da conta</label><input name="email" type="email" required></div></form>`,async()=>{let email=new FormData(document.querySelector('#recoverForm')).get('email'),{error}=await cavaSupabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)throw error;toast('Se o endereço estiver cadastrado, você receberá um link de recuperação.')} );return}modal('Criar conta e empresa',`<form id="signupForm" class="form-grid"><div class="field full"><label>Nome da empresa</label><input name="company" required></div><div class="field full"><label>E-mail</label><input name="email" type="email" autocomplete="email" required></div><div class="field full"><label>Senha</label><input name="password" type="password" minlength="6" autocomplete="new-password" required></div></form>`,async()=>{let f=new FormData(document.querySelector('#signupForm')),email=f.get('email'),password=f.get('password'),company=f.get('company').trim(),{data,error}=await cavaSupabase.auth.signUp({email,password,options:{data:{company_name:company}}});if(error)throw error;if(data.session){authUser=data.user;await initializeApp()}else toast('Conta criada. Confirme o e-mail para acessar a empresa.')})}
async function login(e){e.preventDefault();let f=new FormData(e.target);let {error}=await cavaSupabase.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(error){authPage(error.message);return}await initializeApp()}
async function loadCompanyData(){let m=await cavaSupabase.from('company_members').select('company_id,role').eq('user_id',authUser.id).limit(1).single();sbError(m.error);companyId=m.data.company_id;let [co,settings,projects,prices,compositions,budgets,quantities]=await Promise.all([cavaSupabase.from('companies').select('*').eq('id',companyId).single(),cavaSupabase.from('settings').select('*').eq('company_id',companyId).single(),cavaSupabase.from('projects').select('*').eq('company_id',companyId).order('updated_at',{ascending:false}),cavaSupabase.from('price_items').select('*').eq('company_id',companyId).order('description'),cavaSupabase.from('compositions').select('*,composition_items(*)').eq('company_id',companyId).order('description'),cavaSupabase.from('budgets').select('*,budget_groups(*,budget_items(*))').eq('company_id',companyId),cavaSupabase.from('quantities').select('id,project_id,status').eq('company_id',companyId)]);[co,settings,projects,prices,compositions,budgets,quantities].forEach(x=>sbError(x.error));db.company=co.data;db.defaultBdi=Number(settings.data.bdi_percent);db.bdi=db.defaultBdi;db.projects=projects.data.map(p=>({id:p.id,name:p.name,client:p.client,address:p.address,city:p.city,state:p.state,area:Number(p.area),floors:p.floors,type:p.project_type,standard:p.standard,notes:p.notes,status:p.status,updated:p.updated_at.slice(0,10)}));db.prices=prices.data.map(p=>({id:p.id,code:p.code,description:p.description,category:p.category,unit:p.unit,price:Number(p.unit_price),supplier:p.supplier,region:p.region,source:p.source,date:p.price_date}));db.compositions=compositions.data.map(c=>({id:c.id,code:c.code,description:c.description,unit:c.unit,items:(c.composition_items||[]).map(i=>({id:i.id,price_item_id:i.price_item_id,description:i.description,coef:Number(i.coefficient),price:Number(i.unit_price)}))}));db.budgets=budgets.data;db.budgetGroups=budgets.data.flatMap(b=>b.budget_groups||[]);db.allQuantities=quantities.data;db.quantities=[];db.items=[];db.activeProject=location.hash.startsWith('#project=')?location.hash.slice(9):(db.projects[0]?.id||'');if(!db.projects.some(p=>p.id===db.activeProject))db.activeProject=db.projects[0]?.id||'';}
async function initializeApp(){if(!window.CAVA_SUPABASE_URL||!window.CAVA_SUPABASE_ANON_KEY){authReady=true;authPage('O Supabase ainda não foi configurado. Preencha CAVA_SUPABASE_URL e CAVA_SUPABASE_ANON_KEY em supabase-config.js.');return}if(!cavaSupabase){authReady=true;authPage('A biblioteca Supabase não carregou. Verifique sua conexão e recarregue a página.');return}let {data,error}=await cavaSupabase.auth.getSession();if(error){authPage(error.message);return}authUser=data.session?.user||null;if(!authUser){authPage();return}try{await loadCompanyData();if(db.activeProject)await loadProjectData(db.activeProject);authReady=true;document.querySelector('.sidebar').style.display='';document.querySelector('.topbar').style.display='';document.querySelector('.app-footer').style.display='';document.querySelector('.main').style.marginLeft='';document.querySelector('.company-switch b').textContent=db.company.name;document.querySelector('.company-avatar').textContent=(db.company.name||'C').slice(0,1).toUpperCase();document.querySelector('.breadcrumb').firstChild.textContent=db.company.name+' ';document.querySelector('.user-chip b').textContent=authUser.email;document.querySelector('.user-avatar').textContent=(authUser.email||'U').slice(0,2).toUpperCase();document.querySelector('.top-avatar').textContent=(authUser.email||'U').slice(0,2).toUpperCase();render()}catch(err){authPage(err.message||'Não foi possível carregar os dados da empresa.')}}
function badge(s){let c=s==='Finalizado'||s==='Confirmado'?'green':s==='Em análise'||s==='Estimado'?'yellow':s==='Necessita revisão'?'red':'gray';return `<span class="badge ${c}">${escapeHtml(s)}</span>`}
function projectTable(list){return `<div class="table-wrap"><table><thead><tr><th>Projeto</th><th>Cliente</th><th>Área</th><th>Valor estimado</th><th>Status</th><th>Atualizado</th><th></th></tr></thead><tbody>${list.length?list.map(p=>`<tr><td class="project-name">${escapeHtml(p.name)}<span class="small-muted">${escapeHtml(p.city)}, ${escapeHtml(p.state)}</span></td><td>${escapeHtml(p.client)}</td><td>${num(p.area)} m²</td><td class="project-name">${money(projectTotal(p))}</td><td>${badge(p.status)}</td><td>${p.updated||'01/10/2026'}</td><td><button class="row-action" onclick="openProject('${p.id}')" title="Abrir orçamento">↗</button><button class="row-action" onclick="editProject('${p.id}')" title="Editar projeto">✎</button><button class="row-action" onclick="deleteProject('${p.id}')" title="Excluir projeto">×</button></td></tr>`).join(''):`<tr><td colspan="7"><div class="empty-state">${db.projects.length===0?'Você ainda não possui projetos.':'Nenhum projeto encontrado.'}</div></td></tr>`}</tbody></table></div>`}
function projectTotal(p){let b=(db.budgets||[]).find(x=>x.project_id===p.id),items=(b?.budget_groups||[]).flatMap(g=>g.budget_items||[]),total=calc.directCost(items);return calc.salePrice(total,Number(b?.bdi_percent??db.defaultBdi??0))}
function metric(label,value,note,icon){return `<div class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`}
function dashboard(){let sum=(db.budgets||[]).reduce((s,b)=>{let direct=(b.budget_groups||[]).reduce((n,g)=>n+calc.directCost((g.budget_items||[]).map(i=>({quantity:db.allQuantities.find(q=>q.id===i.quantity_id)?.quantity??i.quantity,unit_price:db.compositions.find(c=>c.id===i.composition_id)?calc.compositionUnitCost(db.compositions.find(c=>c.id===i.composition_id).items):i.unit_price}))),0);return s+calc.salePrice(direct,Number(b.bdi_percent))},0),reviewCount=(db.allQuantities||[]).filter(q=>q.status==='Necessita revisão').length,reviewProject=db.projects.find(p=>p.status==='Em revisão');return `<div class="page-head"><div><h1>Bem-vindo, ${escapeHtml((authUser?.email||'').split('@')[0]||'usuário')} <span style="font-size:19px">☀</span></h1><div class="subhead">Aqui está o resumo da sua operação hoje.</div></div><div class="head-actions"><button class="btn btn-primary" onclick="navigate('novo')">＋ Novo orçamento</button></div></div><div class="metrics">${metric('Projetos',db.projects.length,'Na sua empresa','⌂')}${metric('Orçamentos',db.budgets.length,'Persistidos no workspace','▤')}${metric('Em revisão',db.projects.filter(p=>p.status==='Em revisão').length,'Aguardando validação','◷')}${metric('Valor total orçado',money(sum),'Custo direto + BDI','R$')}</div><div class="dashboard-grid"><section class="card"><div class="card-pad"><div class="card-head"><div><h2>Projetos recentes</h2><div class="subhead">Acompanhe os projetos da sua empresa.</div></div><a class="text-link" onclick="navigate('projetos')">Ver todos →</a></div></div>${projectTable([...db.projects].sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,4))}</section><aside class="card quick-card"><div class="quick-banner"><div class="eyebrow">SEU PRÓXIMO PROJETO</div><h3>Do projeto ao orçamento, em um só lugar.</h3><p>Organize quantitativos, preços e custos da sua obra.</p><button class="btn" onclick="navigate('novo')">＋ Criar orçamento</button></div><h3 style="font-size:11px;margin-bottom:5px">O que precisa de atenção</h3><div class="task-row"><span class="task-icon">◉</span><span><b>Quantitativos para revisar</b><small>${escapeHtml(reviewProject?.name||'Projetos da empresa')}</small></span><span class="task-count">${reviewCount}</span></div></aside></div>`}
function projectsPage(){let list=db.projects.filter(p=>(p.name+p.client+p.city).toLowerCase().includes(projectQuery.toLowerCase()));return `<div class="page-head"><div><h1>Projetos</h1><div class="subhead">Gerencie suas obras e acompanhe o orçamento de cada projeto.</div></div><button class="btn btn-primary" onclick="navigate('novo')">＋ Novo projeto</button></div><div class="filters"><input placeholder="⌕  Buscar projeto ou cliente" value="${escapeHtml(projectQuery)}" oninput="projectQuery=this.value;render()"><select onchange="filterProjects(this.value)"><option value="">Todos os status</option><option>Rascunho</option><option>Em análise</option><option>Em revisão</option><option>Finalizado</option></select><span class="spacer"></span><span class="muted" style="font-size:10px">${list.length} projetos</span></div><section class="card">${projectTable(list)}</section>`}
function workflow(at){let names=['Obra','Documento','Análise','Quantitativos','Orçamento'];return `<div class="workflow">${names.map((x,i)=>`${i?'<span class="step-line"></span>':''}<div class="step ${i<at?'done':''} ${i===at?'active':''}"><span class="step-dot">${i<at?'✓':i+1}</span>${x}</div>`).join('')}</div>`}
function newPage(){return `${`<div class="page-head"><div><h1>Novo orçamento</h1><div class="subhead">Crie a obra e envie o projeto arquitetônico para começar.</div></div></div>`}${workflow(0)}<section class="card wizard-card"><h2 class="section-title">Informações da obra</h2><div class="section-kicker">Os campos com <span class="required">*</span> são obrigatórios.</div><form id="projectForm"><div class="form-grid cols3"><div class="field"><label>Nome da obra <span class="required">*</span></label><input name="name" required placeholder="Ex.: Residência Silva"></div><div class="field"><label>Cliente <span class="required">*</span></label><input name="client" required placeholder="Nome do cliente"></div><div class="field"><label>Tipo de obra</label><select name="type"><option>Residencial</option><option>Comercial</option><option>Reforma</option><option>Outro</option></select></div><div class="field full"><label>Endereço</label><input name="address" placeholder="Rua, número e complemento"></div><div class="field"><label>Cidade</label><input name="city" placeholder="Cidade"></div><div class="field"><label>Estado</label><select name="state"><option>AC</option><option>AL</option><option>AP</option><option>AM</option><option>BA</option><option>CE</option><option>DF</option><option>ES</option><option>GO</option><option>MA</option><option>MT</option><option>MS</option><option>MG</option><option>PA</option><option>PB</option><option>PR</option><option>PE</option><option>PI</option><option>RJ</option><option>RN</option><option>RS</option><option>RO</option><option>RR</option><option>SC</option><option>SP</option><option>SE</option><option>TO</option></select></div><div class="field"><label>Área construída (m²)</label><input name="area" type="number" min="0" step=".01" placeholder="180"></div><div class="field"><label>Número de pavimentos</label><input name="floors" type="number" min="1" value="1"></div><div class="field"><label>Padrão da obra</label><select name="standard"><option>Econômico</option><option selected>Médio</option><option>Alto</option><option>Personalizado</option></select></div><div class="field full"><label>Observações</label><textarea name="notes" placeholder="Informações adicionais sobre a obra"></textarea></div></div><div class="wizard-footer"><button type="button" class="btn" onclick="navigate('projetos')">Cancelar</button><button class="btn btn-primary">Continuar: enviar projeto →</button></div></form></section>`}
function uploadPage(id){let p=db.projects.find(x=>x.id===id);return `<div class="page-head"><div><h1>Novo orçamento</h1><div class="subhead">${escapeHtml(p?.name)} · ${escapeHtml(p?.client)}</div></div></div>${workflow(1)}<section class="card wizard-card"><h2 class="section-title">Projeto arquitetônico</h2><div class="section-kicker">Envie o arquivo PDF para iniciar a preparação da análise.</div><label class="upload-zone" id="dropZone"><input type="file" id="fileInput" accept="application/pdf,.pdf"><div class="upload-icon">↑</div><b>Arraste o PDF para cá ou <span style="color:#9b8047">escolha um arquivo</span></b><p>PDF · Máximo: 20 MB</p></label><div id="fileDisplay"></div>${(db.documents||[]).map(d=>`<div class="file-row"><span class="file-pdf">PDF</span><span><b>${escapeHtml(d.file_name)}</b><small>${new Date(d.created_at).toLocaleDateString('pt-BR')} · Armazenado em bucket privado</small></span><button class="btn btn-sm" onclick="viewDocument('${d.id}')">Visualizar</button><button class="row-action" title="Excluir documento" onclick="deleteDocument('${d.id}')">×</button></div>`).join('')}<div class="notice" style="margin-top:14px">Leitura automática do projeto será adicionada na próxima versão. Nenhum quantitativo é inferido do arquivo.</div><div class="wizard-footer"><button class="btn" onclick="navigate('projetos')">Salvar e sair</button><button class="btn btn-primary" id="analyzeBtn" disabled onclick="startAnalysis('${id}')">Preparar análise →</button></div></section>`}
async function viewDocument(id){let d=(db.documents||[]).find(x=>x.id===id);if(!d)return;let {data,error}=await cavaSupabase.storage.from('project-documents').createSignedUrl(d.storage_path,60);if(error){toast(error.message);return}window.open(data.signedUrl,'_blank','noopener')}
async function deleteDocument(id){let d=(db.documents||[]).find(x=>x.id===id);if(!d)return;if(!confirm(`Excluir o documento \"${d.file_name}\"?`))return;try{let row=await cavaSupabase.from('project_documents').delete().eq('id',id).eq('company_id',companyId).eq('project_id',db.activeProject);sbError(row.error);let removed=await cavaSupabase.storage.from('project-documents').remove([d.storage_path]);if(removed.error){db.documents=db.documents.filter(x=>x.id!==id);render();throw new Error(`Registro removido, mas o arquivo precisa de limpeza no Storage: ${removed.error.message}`)}db.documents=db.documents.filter(x=>x.id!==id);render();toast('Documento excluído.')}catch(err){toast(err.message)}}
let selectedFile=null;
function analysisPage(id){return `<div class="page-head"><div><h1>Preparação da análise</h1><div class="subhead">${escapeHtml(db.projects.find(p=>p.id===id)?.name||'Projeto')}</div></div></div>${workflow(2)}<section class="card wizard-card" style="text-align:center;padding:30px"><div class="upload-icon" style="margin:auto;width:46px;height:46px">⌕</div><h2 style="margin:14px 0 5px">Documento recebido</h2><div class="subhead">Leitura automática do projeto será adicionada na próxima versão.</div><div class="analysis-list"><div class="analysis-item done"><span class="analysis-mark">✓</span>PDF armazenado com acesso privado</div><div class="analysis-item"><span class="analysis-mark">○</span>Quantitativos: adicione e valide os itens manualmente</div></div><div class="head-actions" style="justify-content:center"><button class="btn btn-primary" onclick="navigate('quantitativos')">Ir para quantitativos →</button></div></section>`}
function quantitiesPage(){let project=db.projects.find(p=>p.id===db.activeProject),items=db.quantities.filter(q=>(q.category+q.description).toLowerCase().includes(quantityQuery.toLowerCase()));return `<div class="page-head"><div><h1>Quantitativos</h1><div class="subhead">${escapeHtml(project?.name||'Projeto')} · Revise os quantitativos antes de gerar o orçamento.</div></div><div class="head-actions"><button class="btn" onclick="navigate('upload')">← Projeto</button><button class="btn btn-primary" onclick="navigate('orcamentos')">Gerar orçamento →</button></div></div>${workflow(3)}<div class="summary-cards" style="margin-bottom:15px"><div class="summary-chip"><small>Itens</small><b>${db.quantities.length}</b></div><div class="summary-chip"><small>Confirmados</small><b>${db.quantities.filter(q=>q.status==='Confirmado').length}</b></div><div class="summary-chip"><small>Revisão pendente</small><b style="color:#a64d43">${db.quantities.filter(q=>q.status==='Necessita revisão').length}</b></div></div><div class="quantity-toolbar"><div class="toolbar-left"><input class="search" placeholder="⌕  Buscar serviço" value="${escapeHtml(quantityQuery)}" oninput="quantityQuery=this.value;render()"><button class="btn btn-sm" onclick="addQuantity()">＋ Adicionar item</button></div><div class="toolbar-right"><span style="font-size:9px;color:#92968f">🟢 Confirmado　🟡 Estimado　🔴 Necessita revisão</span></div></div><section class="card"><div class="table-wrap"><table class="quantity-table"><thead><tr><th>Categoria / serviço</th><th>Unidade</th><th>Quantidade</th><th>Perda %</th><th>Quantidade final</th><th>Status</th><th>Origem</th><th></th></tr></thead><tbody>${items.map(q=>`<tr><td><span class="small-muted">${escapeHtml(q.category)}</span><input class="qty-desc" aria-label="Descrição" value="${escapeHtml(q.description)}" onchange="editQuantity('${q.id}','description',this.value)"></td><td><select onchange="editQuantity('${q.id}','unit',this.value)">${['m','m²','m³','kg','un','l','h'].map(u=>`<option ${q.unit===u?'selected':''}>${u}</option>`).join('')}</select></td><td><input type="number" min="0" step=".01" value="${q.quantity}" onchange="editQuantity('${q.id}','quantity',this.value)"></td><td><input type="number" min="0" step=".1" value="${q.loss}" onchange="editQuantity('${q.id}','loss',this.value)"></td><td class="qty-final">${num(calc.finalQuantity(q.quantity,q.loss))} ${escapeHtml(q.unit)}</td><td><select class="status-select" onchange="editQuantity('${q.id}','status',this.value)">${['Confirmado','Estimado','Necessita revisão'].map(s=>`<option ${q.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="source-button" onclick="showOrigin('${q.id}')">Ver origem</button></td><td><button class="row-action" onclick="deleteQuantity('${q.id}')">×</button></td></tr>`).join('')}</tbody></table></div><div class="origin-box" style="padding:12px 15px">Quantidade final = quantidade base × (1 + perda ÷ 100). Os cálculos são executados automaticamente pelo sistema.</div></section>`}
function budgetPage(){let total=calc.directCost(db.items.map(i=>({quantity:effectiveBudgetQuantity(i),price:effectiveBudgetPrice(i)}))),sale=calc.salePrice(total,db.bdi),groups={};db.items.forEach(i=>groups[i.group]=(groups[i.group]||0)+calc.itemCost(effectiveBudgetQuantity(i),effectiveBudgetPrice(i)));let max=Math.max(...Object.values(groups),1),project=db.projects.find(p=>p.id===db.activeProject);return `<div class="page-head"><div><h1>Orçamento</h1><div class="subhead">${escapeHtml(project?.name||'Projeto')} · ${escapeHtml(project?.client||'')} · ${num(project?.area)} m²</div></div><div class="head-actions"><button class="btn" onclick="navigate('upload')">Documentos</button><button class="btn" onclick="navigate('quantitativos')">Quantitativos</button><button class="btn" onclick="exportExcel()">↓ Exportar Excel</button><button class="btn" onclick="window.print()">▤ Exportar PDF</button><button class="btn btn-primary" onclick="addBudgetItem()">＋ Adicionar item</button></div></div>${workflow(4)}<div class="budget-layout"><section class="card"><div class="table-wrap"><table class="budget-table"><thead><tr><th>Etapa / serviço</th><th>Código</th><th>Un.</th><th>Quantidade</th><th>Preço unitário</th><th>Custo total</th><th></th></tr></thead><tbody>${Object.entries(groups).map(([g])=>`<tr class="group-head"><td colspan="7">${escapeHtml(g)}</td></tr>${db.items.filter(x=>x.group===g).map(x=>`<tr><td class="project-name">${escapeHtml(x.description)}</td><td>${escapeHtml(x.code)}</td><td>${escapeHtml(x.unit)}</td><td><input type="number" value="${effectiveBudgetQuantity(x)}" ${x.quantity_id?'readonly title="Derivado do quantitativo vinculado"':''} onchange="editBudget('${x.id}','quantity',this.value)"></td><td><input type="number" value="${effectiveBudgetPrice(x)}" step=".01" ${x.composition_id?'readonly title="Derivado da composição vinculada"':''} onchange="editBudget('${x.id}','price',this.value)"></td><td class="project-name">${money(calc.itemCost(effectiveBudgetQuantity(x),effectiveBudgetPrice(x)))}</td><td><button class="row-action" onclick="deleteBudget('${x.id}')">×</button></td></tr>`).join('')}`).join('')}</tbody></table></div><div class="card-pad" style="border-top:1px solid var(--line);display:flex;justify-content:space-between;font-size:11px"><b>Custo direto</b><b>${money(total)}</b></div></section><aside class="budget-side"><div class="card financial"><h3>Resumo financeiro</h3><div class="financial-line"><span>Custo direto</span><b>${money(total)}</b></div><div class="financial-line"><span>BDI (${num(db.bdi)}%)</span><b>${money(sale-total)}</b></div><div class="financial-line total"><span>Preço final</span><b>${money(sale)}</b></div><div class="field"><label>BDI (%)</label><input type="number" min="0" step=".1" value="${db.bdi}" onchange="updateBdi(this.value)"></div></div><div class="card chart-card"><h3>Resumo por etapa</h3>${Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([g,v])=>`<div class="bar-row"><label>${escapeHtml(g)}</label><div class="bar-track"><div class="bar-fill" style="width:${(v/max*100).toFixed(1)}%"></div></div><b>${(v/(total||1)*100).toFixed(1)}%</b></div>`).join('')}</div>${db.items.length?'':'<div class="notice">Este orçamento está vazio. Adicione itens ao projeto para calcular o custo direto e o BDI.</div>'}</aside></div>`}
function pricePage(){return `<div class="page-head"><div><h1>Banco de preços</h1><div class="subhead">Insumos e serviços da sua empresa, com fonte e região registradas.</div></div><button class="btn btn-primary" onclick="priceModal()">＋ Novo preço</button></div><div class="filters"><input placeholder="⌕  Buscar código ou descrição" oninput="filterTable(this.value,'priceTable')"><select onchange="filterCategory(this.value,'priceTable')"><option value="">Todas as categorias</option><option>Material</option><option>Mão de obra</option><option>Equipamento</option><option>Serviço</option></select><span class="spacer"></span><span class="muted" style="font-size:10px">${db.prices.length} itens</span></div><section class="card"><div class="table-wrap"><table id="priceTable"><thead><tr><th>Código</th><th>Descrição</th><th>Categoria</th><th>Unidade</th><th>Preço unitário</th><th>Fornecedor</th><th>Região</th><th>Atualizado</th><th>Fonte</th><th></th></tr></thead><tbody>${db.prices.map(p=>`<tr data-search="${escapeHtml((p.code+p.description+p.supplier).toLowerCase())}" data-cat="${escapeHtml(p.category)}"><td>${escapeHtml(p.code)}</td><td class="project-name">${escapeHtml(p.description)}</td><td>${escapeHtml(p.category)}</td><td>${escapeHtml(p.unit)}</td><td class="project-name">${money(p.price)}</td><td>${escapeHtml(p.supplier)}</td><td>${escapeHtml(p.region)}</td><td>${escapeHtml(p.date)}</td><td>${escapeHtml(p.source)}</td><td><button class="row-action" onclick="editPrice('${p.code}')">✎</button><button class="row-action" onclick="deletePrice('${p.code}')">×</button></td></tr>`).join('')}</tbody></table></div></section>`}
function compositionsPage(){return `<div class="page-head"><div><h1>Composições</h1><div class="subhead">Monte custos unitários com insumos, mão de obra e coeficientes.</div></div><button class="btn btn-primary" onclick="compositionModal()">＋ Nova composição</button></div><section class="card">${db.compositions.length?db.compositions.map(c=>`<div class="card-pad" style="border-bottom:1px solid var(--line)"><div style="display:flex;justify-content:space-between;align-items:center"><div><h2>${escapeHtml(c.description)}</h2><div class="subhead" style="margin-top:5px">${escapeHtml(c.code)} · unidade ${escapeHtml(c.unit)}</div></div><div style="text-align:right"><b>${money(calc.compositionUnitCost(c.items))} <small class="muted">/ ${escapeHtml(c.unit)}</small></b><div><button class="source-button" onclick="compositionItemModal('${c.id}')">＋ Adicionar insumo</button></div></div></div><div class="table-wrap" style="margin-top:14px"><table><thead><tr><th>Insumo</th><th>Coeficiente</th><th>Preço unitário</th><th>Custo parcial</th><th></th></tr></thead><tbody>${c.items.map(i=>`<tr><td>${escapeHtml(i.description)}</td><td>${num(i.coef)}</td><td>${money(i.price)}</td><td>${money(i.coef*i.price)}</td><td><button class="row-action" onclick="deleteCompositionItem('${i.id}','${c.id}')">×</button></td></tr>`).join('')||'<tr><td colspan="5">Adicione itens do banco de preços para calcular o custo unitário.</td></tr>'}</tbody></table></div></div>`).join(''):'<div class="empty-state"><b>Nenhuma composição cadastrada</b>Crie a primeira composição para sua empresa.</div>'}</section>`}
function compositionItemModal(compositionId){let c=db.compositions.find(x=>x.id===compositionId);modal(`Insumo · ${escapeHtml(c.description)}`,`<form id="compositionItemForm" class="form-grid"><div class="field full"><label>Insumo do banco de preços</label><select name="priceId" required>${db.prices.map(p=>`<option value="${p.id}">${escapeHtml(p.code)} · ${escapeHtml(p.description)} (${money(p.price)}/${escapeHtml(p.unit)})</option>`).join('')}</select></div><div class="field"><label>Coeficiente</label><input type="number" step=".0001" min="0" name="coefficient" value="1" required></div></form>`,async()=>{let f=new FormData(document.querySelector('#compositionItemForm')),p=db.prices.find(x=>x.id===f.get('priceId'));if(!p)throw Error('Cadastre um preço primeiro.');let row={company_id:companyId,composition_id:c.id,price_item_id:p.id,description:p.description,coefficient:Number(f.get('coefficient')),unit_price:p.price,position:c.items.length};let {data,error}=await cavaSupabase.from('composition_items').insert(row).select('*').single();sbError(error);c.items.push({id:data.id,price_item_id:p.id,description:p.description,coef:Number(data.coefficient),price:Number(data.unit_price)});await syncCompositionBudgetItems(c);render()})}
async function syncCompositionBudgetItems(c){let price=calc.compositionUnitCost(c.items);let {error}=await cavaSupabase.from('budget_items').update({unit_price:price,unit:c.unit}).eq('company_id',companyId).eq('composition_id',c.id);sbError(error);for(const b of db.budgets)for(const g of b.budget_groups||[])for(const i of g.budget_items||[])if(i.composition_id===c.id){i.unit_price=price;i.unit=c.unit}if(db.activeProject)await loadProjectData(db.activeProject)}
async function deleteCompositionItem(id,compositionId){try{let {error}=await cavaSupabase.from('composition_items').delete().eq('id',id);sbError(error);let c=db.compositions.find(x=>x.id===compositionId);c.items=c.items.filter(x=>x.id!==id);await syncCompositionBudgetItems(c);render()}catch(err){toast(err.message)}}
function settingsPage(){return `<div class="page-head"><div><h1>Configurações</h1><div class="subhead">Preferências da empresa e do orçamento.</div></div></div><section class="card wizard-card" style="max-width:700px"><h2 class="section-title">Empresa</h2><div class="form-grid"><div class="field"><label>Nome da empresa</label><input id="companyName" value="${escapeHtml(db.company?.name)}"></div><div class="field"><label>BDI padrão (%)</label><input id="companyBdi" type="number" value="${db.defaultBdi??db.bdi}"></div><div class="field"><label>Moeda</label><select disabled><option>BRL — Real brasileiro (R$)</option></select></div><div class="field"><label>Unidade de área</label><select disabled><option>m² — Metro quadrado</option></select></div></div><div class="notice" style="margin-top:20px">Dados de projetos, quantitativos, preços e orçamento são sincronizados com o Supabase. Documentos ficam em armazenamento privado e são exibidos por links temporários.</div><div class="wizard-footer"><span class="muted" style="font-size:10px">Conta: ${escapeHtml(authUser?.email)}</span><button class="btn btn-primary" onclick="saveSettings()">Salvar alterações</button></div></section>`}
async function saveSettings(){let name=document.querySelector('#companyName').value.trim(),bdi=Number(document.querySelector('#companyBdi').value)||0;try{let co=await cavaSupabase.from('companies').update({name}).eq('id',companyId);sbError(co.error);let st=await cavaSupabase.from('settings').update({bdi_percent:bdi}).eq('company_id',companyId);sbError(st.error);db.company.name=name;db.defaultBdi=bdi;if(!db.budgets.some(b=>b.project_id===db.activeProject))db.bdi=bdi;document.querySelector('.company-switch b').textContent=name;toast('Configurações salvas.')}catch(err){toast(err.message)}}
function render(){let hash=location.hash.slice(1);if(hash==='upload')current='upload';else if(hash==='analysis')current='analysis';else if(pageNames[hash])current=hash;else current='dashboard';let app=document.querySelector('#app');document.querySelector('#crumb').textContent=pageNames[current]||'Novo orçamento';document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===current));if(current==='dashboard')app.innerHTML=dashboard();if(current==='projetos')app.innerHTML=projectsPage();if(current==='novo')app.innerHTML=newPage();if(current==='upload')app.innerHTML=uploadPage(db.activeProject);if(current==='analysis')app.innerHTML=analysisPage(db.activeProject);if(current==='quantitativos')app.innerHTML=quantitiesPage();if(current==='orcamentos')app.innerHTML=budgetPage();if(current==='precos')app.innerHTML=pricePage();if(current==='composicoes')app.innerHTML=compositionsPage();if(current==='configuracoes')app.innerHTML=settingsPage();if(current==='upload')wireUpload();if(current==='novo')document.querySelector('#projectForm').addEventListener('submit',createProject)}
function navigate(page){location.hash=page;document.querySelector('#sidebar').classList.remove('open')}window.addEventListener('hashchange',render);
document.querySelectorAll('[data-page]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();navigate(a.dataset.page)}));document.querySelector('#menuToggle').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');
async function createProject(e){e.preventDefault();try{let f=new FormData(e.target),p=Object.fromEntries(f.entries());let row={company_id:companyId,name:p.name,client:p.client,address:p.address,city:p.city,state:p.state,project_type:p.type,area:Number(p.area)||0,floors:Number(p.floors)||1,standard:p.standard,notes:p.notes,status:'Rascunho',created_by:authUser.id};let {data,error}=await cavaSupabase.from('projects').insert(row).select('*').single();sbError(error);db.projects.unshift({id:data.id,name:data.name,client:data.client,address:data.address,city:data.city,state:data.state,area:Number(data.area),floors:data.floors,type:data.project_type,standard:data.standard,notes:data.notes,status:data.status,updated:data.updated_at.slice(0,10)});db.activeProject=data.id;db.quantities=[];db.items=[];db.documents=[];selectedFile=null;navigate('upload');toast('Obra criada. Envie o projeto arquitetônico.')}catch(err){toast(err.message)}}
function wireUpload(){let input=document.querySelector('#fileInput'),zone=document.querySelector('#dropZone');if(!input)return;input.onchange=()=>useFile(input.files[0]);zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag')};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');useFile(e.dataTransfer.files[0])}}
async function useFile(file){if(!file)return;const button=document.querySelector('#analyzeBtn');button.disabled=true;selectedFile=null;try{if(!file.name.toLowerCase().endsWith('.pdf'))throw Error('O arquivo precisa ter extensão PDF.');if(file.size===0||file.size>20*1024*1024)throw Error('O PDF deve ter até 20 MB e não pode estar vazio.');const signature=new TextDecoder().decode(await file.slice(0,5).arrayBuffer());if(signature!=='%PDF-')throw Error('O arquivo selecionado não tem assinatura válida de PDF.');selectedFile=file;document.querySelector('#fileDisplay').innerHTML=`<div class="file-row"><span class="file-pdf">PDF</span><span><b>${escapeHtml(file.name)}</b><small>${(file.size/1024/1024).toFixed(2)} MB · Arquivo nesta sessão</small></span><button class="remove" onclick="selectedFile=null;document.querySelector('#fileDisplay').innerHTML='';document.querySelector('#analyzeBtn').disabled=true">×</button></div>`;button.disabled=false}catch(err){toast(err.message)}}
async function startAnalysis(id){if(!selectedFile){toast('Selecione um PDF primeiro.');return}let uploadedPath=null,uploadedDocId=null;try{let path=`${companyId}/${id}/${uuid()}.pdf`;uploadedPath=path;let {error:uploadError}=await cavaSupabase.storage.from('project-documents').upload(path,selectedFile,{contentType:'application/pdf',upsert:false});sbError(uploadError);let doc=await cavaSupabase.from('project_documents').insert({company_id:companyId,project_id:id,storage_path:path,file_name:selectedFile.name,mime_type:'application/pdf',size_bytes:selectedFile.size,uploaded_by:authUser.id}).select('*').single();sbError(doc.error);uploadedDocId=doc.data.id;db.activeDocument=doc.data.id;db.documents=[doc.data,...(db.documents||[])];let analysis=await cavaSupabase.from('project_analysis').insert({company_id:companyId,project_id:id,document_id:doc.data.id,status:'pending',provider:'manual-preparation'});sbError(analysis.error);let upd=await cavaSupabase.from('projects').update({status:'Em análise'}).eq('id',id);sbError(upd.error);let p=db.projects.find(x=>x.id===id);if(p)p.status='Em análise';selectedFile=null;navigate('analysis')}catch(err){if(uploadedDocId){let row=await cavaSupabase.from('project_documents').delete().eq('id',uploadedDocId);if(row.error)console.error(row.error);db.documents=(db.documents||[]).filter(d=>d.id!==uploadedDocId)}if(uploadedPath){let cleanup=await cavaSupabase.storage.from('project-documents').remove([uploadedPath]);if(cleanup.error)console.error(cleanup.error)}toast(`Falha no envio: ${err.message}`)}}

async function editQuantity(id,key,value){let q=db.quantities.find(x=>x.id===id);if(!q)return;q[key]=['quantity','loss'].includes(key)?Number(value)||0:value;try{await persistQuantity(q);render()}catch(err){toast(err.message)}}
async function deleteQuantity(id){try{let {error}=await cavaSupabase.from('quantities').delete().eq('id',id);sbError(error);db.quantities=db.quantities.filter(q=>q.id!==id);render();toast('Quantitativo removido.')}catch(err){toast(err.message)}}
function addQuantity(){modal('Novo quantitativo',`<form id="newQuantity" class="form-grid"><div class="field"><label>Categoria</label><input name="category" required placeholder="Ex.: Alvenaria"></div><div class="field"><label>Descrição</label><input name="description" required placeholder="Ex.: Alvenaria de bloco"></div><div class="field"><label>Unidade</label><select name="unit">${['m','m²','m³','kg','un','l','h'].map(x=>`<option>${x}</option>`)}</select></div><div class="field"><label>Quantidade base</label><input name="quantity" type="number" step=".01" value="0"></div><div class="field"><label>Perda (%)</label><input name="loss" type="number" step=".1" value="0"></div><div class="field"><label>Documento de origem</label><select name="document_id"><option value="">Sem documento</option>${(db.documents||[]).map(d=>`<option value="${d.id}">${escapeHtml(d.file_name)}</option>`).join('')}</select></div><div class="field"><label>Página</label><input name="page" type="number" min="1"></div><div class="field"><label>Ambiente</label><input name="room" placeholder="Ex.: Sala"></div><div class="field"><label>Elemento</label><input name="element" placeholder="Ex.: Piso"></div><div class="field full"><label>Método de cálculo</label><input name="method" placeholder="Ex.: área medida no projeto + perda"></div><div class="field full"><label>Observação</label><textarea name="observation"></textarea></div></form>`,async()=>{let f=new FormData(document.querySelector('#newQuantity')),q=Object.fromEntries(f.entries());q.id=uuid();q.quantity=Number(q.quantity);q.loss=Number(q.loss);q.page=Number(q.page)||null;q.document_id=q.document_id||null;q.status='Necessita revisão';q.sources=q.document_id||q.page||q.room||q.element||q.observation||q.method?[{document_id:q.document_id,page:q.page,room_label:q.room,element_label:q.element,observation:q.observation,calculation_method:q.method}]:[];q.document=(db.documents||[]).find(d=>d.id===q.document_id)?.file_name||'Cadastro manual';q.method=q.method||'Informado manualmente pelo usuário.';try{await persistQuantity(q);render();toast('Quantitativo adicionado.')}catch(err){toast(err.message)}})}
function showOrigin(id){let q=db.quantities.find(x=>x.id===id);if(!q)return;let sources=q.sources||[];modal('Origem do quantitativo',`<dl class="origin-list"><dt>Serviço</dt><dd>${escapeHtml(q.description)}</dd><dt>Quantidade base</dt><dd>${num(q.quantity)} ${escapeHtml(q.unit)}</dd><dt>Perda</dt><dd>${num(q.loss)}%</dd><dt>Quantidade final</dt><dd>${num(calc.finalQuantity(q.quantity,q.loss))} ${escapeHtml(q.unit)}</dd></dl><h3>Fontes de origem</h3>${sources.length?sources.map((src,i)=>`<dl class="origin-list"><dt>Fonte ${i+1}</dt><dd>${escapeHtml(src.document||'Sem documento')}</dd><dt>Página</dt><dd>${escapeHtml(src.page||'—')}</dd><dt>Ambiente</dt><dd>${escapeHtml(src.room_label||'—')}</dd><dt>Elemento</dt><dd>${escapeHtml(src.element_label||'—')}</dd><dt>Método de cálculo</dt><dd>${escapeHtml(src.calculation_method||'—')}</dd><dt>Observação</dt><dd>${escapeHtml(src.observation||'—')}</dd></dl>`).join(''):'<p>Cadastro manual</p><p>Sem documento ou página informados.</p>'}<button class="btn" onclick="addQuantitySource('${id}')">＋ Adicionar origem</button>`)}
function addQuantitySource(id){let q=db.quantities.find(x=>x.id===id);if(!q)return;modal('Adicionar origem',`<form id="sourceForm" class="form-grid"><div class="field full"><label>Documento</label><select name="document_id"><option value="">Sem documento</option>${db.documents.map(d=>`<option value="${d.id}">${escapeHtml(d.file_name)}</option>`).join('')}</select></div><div class="field"><label>Página</label><input name="page" type="number" min="1"></div><div class="field"><label>Ambiente</label><input name="room_label"></div><div class="field"><label>Elemento</label><input name="element_label"></div><div class="field full"><label>Método de cálculo</label><input name="calculation_method"></div><div class="field full"><label>Observação</label><textarea name="observation"></textarea></div></form>`,async()=>{let f=Object.fromEntries(new FormData(document.querySelector('#sourceForm')).entries()),src={document_id:f.document_id||null,page:Number(f.page)||null,room_label:f.room_label||null,element_label:f.element_label||null,calculation_method:f.calculation_method||null,observation:f.observation||null};q.sources=q.sources||[];q.sources.push(src);await persistQuantity(q);render();showOrigin(id);toast('Origem adicionada.')})}
async function openProject(id){db.activeProject=id;try{await loadProjectData(id);navigate('orcamentos')}catch(err){toast(err.message)}}
function editProject(id){let p=db.projects.find(x=>x.id===id);if(!p)return;modal('Editar projeto',`<form id="editProjectForm" class="form-grid"><div class="field"><label>Nome da obra</label><input name="name" required value="${escapeHtml(p.name)}"></div><div class="field"><label>Cliente</label><input name="client" required value="${escapeHtml(p.client)}"></div><div class="field"><label>Endereço</label><input name="address" value="${escapeHtml(p.address)}"></div><div class="field"><label>Cidade</label><input name="city" value="${escapeHtml(p.city)}"></div><div class="field"><label>Estado</label><input name="state" value="${escapeHtml(p.state)}"></div><div class="field"><label>Tipo</label><select name="type">${['Residencial','Comercial','Reforma','Outro'].map(v=>`<option ${p.type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Área (m²)</label><input name="area" type="number" value="${p.area}"></div><div class="field"><label>Pavimentos</label><input name="floors" type="number" value="${p.floors}"></div><div class="field"><label>Padrão</label><select name="standard">${['Econômico','Médio','Alto','Personalizado'].map(v=>`<option ${p.standard===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Rascunho','Em análise','Em revisão','Finalizado'].map(v=>`<option ${p.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Observações</label><textarea name="notes">${escapeHtml(p.notes)}</textarea></div></form>`,async()=>{let x=Object.fromEntries(new FormData(document.querySelector('#editProjectForm')).entries());try{let {error}=await cavaSupabase.from('projects').update({name:x.name,client:x.client,address:x.address,city:x.city,state:x.state,project_type:x.type,area:Number(x.area),floors:Number(x.floors),standard:x.standard,notes:x.notes,status:x.status}).eq('id',id);sbError(error);Object.assign(p,{...x,area:Number(x.area),floors:Number(x.floors)});render();toast('Projeto atualizado.')}catch(err){toast(err.message)}})}
async function deleteProject(id){if(!confirm('Excluir esta obra e seus dados relacionados? Esta ação não pode ser desfeita.'))return;try{let docs=await cavaSupabase.from('project_documents').select('storage_path').eq('company_id',companyId).eq('project_id',id);sbError(docs.error);if(docs.data.length){let removed=await cavaSupabase.storage.from('project-documents').remove(docs.data.map(d=>d.storage_path));sbError(removed.error)}let {error}=await cavaSupabase.from('projects').delete().eq('id',id);sbError(error);db.projects=db.projects.filter(p=>p.id!==id);db.documents=[];db.budgets=db.budgets.filter(b=>b.project_id!==id);db.allQuantities=db.allQuantities.filter(q=>q.project_id!==id);if(db.activeProject===id){db.activeProject=db.projects[0]?.id||'';db.quantities=[];db.items=[];db.bdi=Number(db.defaultBdi||0)}render();toast('Projeto excluído.')}catch(err){toast(err.message)}}
async function loadProjectData(id){db.activeProject=id;let [q,b,d]=await Promise.all([cavaSupabase.from('quantities').select('*,quantity_sources(*)').eq('company_id',companyId).eq('project_id',id),cavaSupabase.from('budgets').select('*,budget_groups(*,budget_items(*))').eq('company_id',companyId).eq('project_id',id).maybeSingle(),cavaSupabase.from('project_documents').select('*').eq('company_id',companyId).eq('project_id',id).order('created_at',{ascending:false})]);[q,b,d].forEach(x=>sbError(x.error));db.documents=d.data;db.quantities=q.data.map(v=>{let sources=(v.quantity_sources||[]).map(src=>({...src,document:d.data.find(doc=>doc.id===src.document_id)?.file_name||null}));return{id:v.id,category:v.category,description:v.description,unit:v.unit,quantity:Number(v.quantity),loss:Number(v.loss_percent),status:v.status,sources,document_id:sources[0]?.document_id||null,document:sources[0]?.document||'Cadastro manual',page:sources[0]?.page,room:sources[0]?.room_label||'—',element:sources[0]?.element_label||v.description,method:sources[0]?.calculation_method||'Informado manualmente pelo usuário.'}});db.budgets=db.budgets.filter(x=>x.project_id!==id);if(b.data)db.budgets.push(b.data);db.budgetGroups=db.budgets.flatMap(x=>x.budget_groups||[]);db.items=(b.data?.budget_groups||[]).flatMap(g=>(g.budget_items||[]).map(i=>({id:i.id,group:g.name,group_id:g.id,budget_id:i.budget_id,description:i.description,code:i.code,unit:i.unit,quantity:Number(i.quantity),price:Number(i.unit_price),quantity_id:i.quantity_id,composition_id:i.composition_id})));db.bdi=b.data?Number(b.data.bdi_percent):Number(db.defaultBdi||0)}
function filterProjects(v){projectQuery=v;render()}
async function editBudget(id,key,value){let x=db.items.find(i=>i.id===id);if(x)x[key]=Number(value)||0;try{await persistBudgetItem(x);render()}catch(err){toast(err.message)}}
async function deleteBudget(id){try{let {error}=await cavaSupabase.from('budget_items').delete().eq('id',id);sbError(error);db.items=db.items.filter(i=>i.id!==id);render()}catch(err){toast(err.message)}}
function applyBudgetQuantity(id){let q=db.quantities.find(x=>x.id===id),form=document.querySelector('#newBudget');if(!q||!form)return;form.elements.description.value=q.description;form.elements.unit.value=q.unit;form.elements.quantity.value=calc.finalQuantity(q.quantity,q.loss)}
function applyBudgetComposition(id){let c=db.compositions.find(x=>x.id===id),form=document.querySelector('#newBudget');if(!c||!form)return;form.elements.description.value=c.description;form.elements.unit.value=c.unit;form.elements.price.value=calc.compositionUnitCost(c.items)}
function addBudgetItem(){modal('Adicionar item ao orçamento',`<form id="newBudget" class="form-grid"><div class="field"><label>Etapa</label><select name="group">${['Serviços preliminares','Fundação','Estrutura','Alvenaria','Cobertura','Esquadrias','Instalações','Revestimentos','Pintura','Serviços externos'].map(x=>`<option>${x}</option>`)}</select></div><div class="field"><label>Código</label><input name="code" value="CAV-${String(db.items.length+1).padStart(3,'0')}"></div><div class="field full"><label>Descrição</label><input name="description" required></div><div class="field"><label>Quantitativo opcional</label><select name="quantity_id" onchange="applyBudgetQuantity(this.value)"><option value="">Sem vínculo</option>${db.quantities.map(q=>`<option value="${q.id}">${escapeHtml(q.description)}</option>`).join('')}</select></div><div class="field"><label>Composição opcional</label><select name="composition_id" onchange="applyBudgetComposition(this.value)"><option value="">Sem composição</option>${db.compositions.map(c=>`<option value="${c.id}">${escapeHtml(c.code)} · ${escapeHtml(c.description)}</option>`).join('')}</select></div><div class="field"><label>Unidade</label><select name="unit">${['m','m²','m³','kg','un','l','h'].map(x=>`<option>${x}</option>`)}</select></div><div class="field"><label>Quantidade</label><input name="quantity" type="number" step=".01" value="1"></div><div class="field"><label>Preço unitário (R$)</label><input name="price" type="number" step=".01" value="0"></div></form>`,async()=>{let x=Object.fromEntries(new FormData(document.querySelector('#newBudget')).entries());x.id=uuid();x.quantity=Number(x.quantity);x.price=Number(x.price);x.composition_id=x.composition_id||null;x.quantity_id=x.quantity_id||null;try{await persistBudgetItem(x);render()}catch(err){toast(err.message)}})}

function compositionModal(){modal('Nova composição',`<form id="newComp" class="form-grid"><div class="field"><label>Código</label><input name="code" required placeholder="COMP-002"></div><div class="field"><label>Unidade</label><select name="unit">${['m²','m³','m','kg','un','h'].map(x=>`<option>${x}</option>`)}</select></div><div class="field full"><label>Descrição</label><input name="description" required></div><div class="field full"><label>Insumos</label><div style="font-size:10px;color:#888">Cadastre os itens associados na composição.</div></div></form>`,async()=>{let x=Object.fromEntries(new FormData(document.querySelector('#newComp')).entries());let row={id:uuid(),company_id:companyId,code:x.code,description:x.description,unit:x.unit};let {data,error}=await cavaSupabase.from('compositions').insert(row).select('*').single();sbError(error);db.compositions.push({...data,items:[]});render();toast('Composição criada.')})}
function priceModal(item){modal(item?'Editar preço':'Novo preço',`<form id="priceForm" class="form-grid">${[['code','Código',item?.code||'INS-003'],['description','Descrição',item?.description||''],['category','Categoria',item?.category||'Material'],['unit','Unidade',item?.unit||'un'],['price','Preço unitário',item?.price||''],['supplier','Fornecedor',item?.supplier||''],['region','Região',item?.region||''],['date','Data de atualização',item?.date||new Date().toISOString().slice(0,10)],['source','Fonte',item?.source||'Cotação própria']].map(([k,l,v])=>`<div class="field"><label>${l}</label><input name="${k}" value="${escapeHtml(v)}" ${k==='code'||k==='description'?'required':''} ${k==='price'?'type="number" step=".01"':''}></div>`).join('')}</form>`,async()=>{let x=Object.fromEntries(new FormData(document.querySelector('#priceForm')).entries());x.id=item?.id||uuid();x.price=Number(x.price);try{await persistPrice(x);let idx=db.prices.findIndex(a=>a.id===item?.id);if(idx>=0)db.prices[idx]=x;else db.prices.push(x);render();toast('Preço salvo.')}catch(err){toast(err.message)}})}
function editPrice(code){let x=db.prices.find(p=>p.code===code);if(x)priceModal(x)}async function deletePrice(code){let p=db.prices.find(x=>x.code===code);try{let {error}=await cavaSupabase.from('price_items').delete().eq('id',p.id);sbError(error);db.prices=db.prices.filter(x=>x.id!==p.id);render();toast('Preço removido.')}catch(err){toast(err.message)}}
function filterTable(query,id){document.querySelectorAll(`#${id} tbody tr`).forEach(tr=>tr.hidden=!tr.dataset.search?.includes(query.toLowerCase()))}function filterCategory(cat,id){document.querySelectorAll(`#${id} tbody tr`).forEach(tr=>tr.hidden=!!cat&&tr.dataset.cat!==cat)}
function exportExcel(){let p=db.projects.find(x=>x.id===db.activeProject),direct=calc.directCost(db.items.map(i=>({quantity:effectiveBudgetQuantity(i),price:effectiveBudgetPrice(i)}))),rows=[['Projeto',p?.name],['Cliente',p?.client],['Data',new Date().toLocaleDateString('pt-BR')],['Área (m²)',p?.area],[],['Etapa','Código','Descrição','Unidade','Quantidade','Preço unitário','Custo total'],...db.items.map(i=>[i.group,i.code,i.description,i.unit,effectiveBudgetQuantity(i),effectiveBudgetPrice(i),calc.itemCost(effectiveBudgetQuantity(i),effectiveBudgetPrice(i))]),[],['','','Custo direto','','','',direct],['','','BDI',`${db.bdi}%`],['','','Preço final','','','',calc.salePrice(direct,db.bdi)]];let csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),`orcamento-${(p?.name||'obra').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-')}.csv`);toast('Orçamento exportado em formato compatível com Excel.')}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function modal(title,body,onSave){let root=document.querySelector('#modalRoot');root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" id="modalSave">Salvar</button></div></div></div>`;document.querySelector('#modalSave').onclick=async()=>{let form=root.querySelector('form');if(form&&!form.reportValidity())return;try{await onSave();if(root.querySelector('.modal'))closeModal()}catch(err){toast(err.message||'Não foi possível salvar.')}}}
function closeModal(){document.querySelector('#modalRoot').innerHTML=''}

window.render=render;window.navigate=navigate;window.filterProjects=filterProjects;window.openProject=openProject;window.editProject=editProject;window.deleteProject=deleteProject;window.editQuantity=editQuantity;window.deleteQuantity=deleteQuantity;window.addQuantity=addQuantity;window.showOrigin=showOrigin;window.addQuantitySource=addQuantitySource;window.startAnalysis=startAnalysis;window.viewDocument=viewDocument;window.deleteDocument=deleteDocument;window.editBudget=editBudget;window.deleteBudget=deleteBudget;window.addBudgetItem=addBudgetItem;window.applyBudgetQuantity=applyBudgetQuantity;window.applyBudgetComposition=applyBudgetComposition;window.compositionModal=compositionModal;window.deleteCompositionItem=deleteCompositionItem;window.priceModal=priceModal;window.editPrice=editPrice;window.deletePrice=deletePrice;window.exportExcel=exportExcel;window.closeModal=closeModal;window.filterTable=filterTable;window.filterCategory=filterCategory;window.logout=logout;window.updateBdi=updateBdi;window.authAction=authAction;window.saveSettings=saveSettings;
if(window.CAVA_SUPABASE_URL&&window.CAVA_SUPABASE_ANON_KEY&&window.supabase?.createClient){cavaSupabase=window.supabase.createClient(window.CAVA_SUPABASE_URL,window.CAVA_SUPABASE_ANON_KEY);cavaSupabase.auth.onAuthStateChange((event)=>{if(event==='PASSWORD_RECOVERY'){document.querySelector('#app').innerHTML=`<div class="login-shell"><div class="login-card"><div class="login-brand">CAVA<span>+</span> ORÇA</div><h1>Nova senha</h1><form id="newPasswordForm"><div class="field"><label>Nova senha</label><input name="password" type="password" minlength="6" required></div><button class="btn btn-primary">Salvar senha</button></form></div></div>`;document.querySelector('#newPasswordForm').onsubmit=async e=>{e.preventDefault();let pw=new FormData(e.target).get('password');let {error}=await cavaSupabase.auth.updateUser({password:pw});if(error)toast(error.message);else{toast('Senha atualizada.');await initializeApp()}}}})}
